CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS full_name text NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN IF NOT EXISTS phone text NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN IF NOT EXISTS password_hash text;
CREATE TABLE IF NOT EXISTS oauth_states (hash text PRIMARY KEY, verifier text NOT NULL, nonce_hash text NOT NULL, return_to text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS login_tokens (hash text PRIMARY KEY, email text NOT NULL, expires_at timestamptz NOT NULL);
ALTER TABLE login_tokens ADD COLUMN IF NOT EXISTS password_hash text;
ALTER TABLE login_tokens ADD COLUMN IF NOT EXISTS remember boolean NOT NULL DEFAULT false;
ALTER TABLE oauth_states ADD COLUMN IF NOT EXISTS remember boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS sessions (hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS events (id uuid PRIMARY KEY, title text NOT NULL, city text NOT NULL, venue text NOT NULL, starts_at timestamptz NOT NULL, price integer NOT NULL CHECK(price>=100), capacity integer NOT NULL CHECK(capacity>0), sales_open boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), event_id uuid NOT NULL REFERENCES events(id), quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 6), amount integer NOT NULL CHECK(amount>0), razorpay_order_id text UNIQUE, payment_id text UNIQUE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','failed')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tickets (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), ordinal integer NOT NULL, checked_in_at timestamptz, UNIQUE(order_id,ordinal));
CREATE TABLE IF NOT EXISTS email_queue (id uuid PRIMARY KEY, recipient text NOT NULL, subject text NOT NULL, body text NOT NULL, sent_at timestamptz, attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_event_idx ON orders(event_id,status);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS provider_attempted boolean NOT NULL DEFAULT false;
CREATE INDEX IF NOT EXISTS sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS audit_logs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor text NOT NULL, action text NOT NULL, entity text NOT NULL, record_id text NOT NULL, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION forbid_delete() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Permanent business records cannot be deleted'; END $$;
CREATE OR REPLACE FUNCTION record_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO audit_logs(actor,action,entity,record_id,before_data,after_data) VALUES(coalesce(nullif(current_setting('twktk.actor',true),''),'system'),TG_OP,TG_TABLE_NAME,NEW.id::text,CASE WHEN TG_OP='UPDATE' THEN (to_jsonb(OLD)-'password_hash') ELSE NULL END,(to_jsonb(NEW)-'password_hash')); RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['events','orders','tickets','users','email_queue'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS no_delete ON %I',t); EXECUTE format('CREATE TRIGGER no_delete BEFORE DELETE ON %I FOR EACH ROW EXECUTE FUNCTION forbid_delete()',t); END LOOP; FOREACH t IN ARRAY ARRAY['events','orders','tickets','users','email_queue'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS history ON %I',t); EXECUTE format('CREATE TRIGGER history AFTER INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION record_audit()',t); END LOOP; END $$;
DROP TRIGGER IF EXISTS audit_immutable ON audit_logs;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION forbid_delete();
CREATE OR REPLACE FUNCTION protect_booking() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.created_at<>OLD.created_at OR NEW.amount<>OLD.amount OR NEW.quantity<>OLD.quantity OR NEW.user_id<>OLD.user_id OR NEW.event_id<>OLD.event_id OR NEW.ticket_type_id IS DISTINCT FROM OLD.ticket_type_id OR NEW.admissions<>OLD.admissions OR NEW.attendee_name<>OLD.attendee_name OR NEW.attendee_phone<>OLD.attendee_phone OR (OLD.status='paid' AND NEW.status<>'paid') OR (OLD.razorpay_order_id IS NOT NULL AND NEW.razorpay_order_id IS DISTINCT FROM OLD.razorpay_order_id) OR (OLD.payment_id IS NOT NULL AND NEW.payment_id IS DISTINCT FROM OLD.payment_id) THEN RAISE EXCEPTION 'Original booking details cannot be rewritten'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS booking_immutable ON orders;
CREATE TRIGGER booking_immutable BEFORE UPDATE ON orders FOR EACH ROW EXECUTE FUNCTION protect_booking();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['events','orders','tickets','users','email_queue','audit_logs'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS no_truncate ON %I',t); EXECUTE format('CREATE TRIGGER no_truncate BEFORE TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION forbid_delete()',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION protect_ticket() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.order_id<>OLD.order_id OR NEW.ordinal<>OLD.ordinal OR (OLD.checked_in_at IS NOT NULL AND NEW.checked_in_at IS DISTINCT FROM OLD.checked_in_at) THEN RAISE EXCEPTION 'Original ticket details cannot be rewritten'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS ticket_immutable ON tickets;
CREATE TRIGGER ticket_immutable BEFORE UPDATE ON tickets FOR EACH ROW EXECUTE FUNCTION protect_ticket();
INSERT INTO events(id,title,city,venue,starts_at,price,capacity,sales_open) VALUES ('33333333-3333-4333-8333-333333333331','TWKTK — Delhi','Delhi','Venue to be announced','2026-10-31T18:00:00+05:30',199900,2200,false),('33333333-3333-4333-8333-333333333332','TWKTK — Bengaluru','Bengaluru','Venue to be announced','2026-11-01T18:00:00+05:30',199900,2200,false) ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS ticket_types (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES events(id), name text NOT NULL, price integer NOT NULL CHECK(price>=100), capacity integer NOT NULL CHECK(capacity>0), admissions integer NOT NULL DEFAULT 1 CHECK(admissions BETWEEN 1 AND 6), sales_open boolean NOT NULL DEFAULT false, UNIQUE(event_id,name));
ALTER TABLE orders ADD COLUMN IF NOT EXISTS ticket_type_id uuid REFERENCES ticket_types(id);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS admissions integer NOT NULL DEFAULT 1 CHECK(admissions BETWEEN 1 AND 6);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS attendee_name text NOT NULL DEFAULT '';
ALTER TABLE orders ADD COLUMN IF NOT EXISTS attendee_phone text NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS world_profiles (id uuid PRIMARY KEY REFERENCES users(id), prefs jsonb NOT NULL DEFAULT '{}');
UPDATE users u SET full_name=o.attendee_name,phone=o.attendee_phone FROM (SELECT DISTINCT ON (user_id) user_id,attendee_name,attendee_phone FROM orders WHERE attendee_name<>'' ORDER BY user_id,created_at DESC,id DESC) o WHERE u.id=o.user_id AND u.full_name='' AND u.phone='';
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['ticket_types','world_profiles'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS no_delete ON %I',t); EXECUTE format('CREATE TRIGGER no_delete BEFORE DELETE ON %I FOR EACH ROW EXECUTE FUNCTION forbid_delete()',t); EXECUTE format('DROP TRIGGER IF EXISTS no_truncate ON %I',t); EXECUTE format('CREATE TRIGGER no_truncate BEFORE TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION forbid_delete()',t); EXECUTE format('DROP TRIGGER IF EXISTS history ON %I',t); EXECUTE format('CREATE TRIGGER history AFTER INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION record_audit()',t); END LOOP; END $$;
INSERT INTO ticket_types(event_id,name,price,capacity,admissions) SELECT e.id,t.name,CASE WHEN t.name='GENERAL ACCESS' THEN e.price WHEN t.name='VIP' THEN 399900 WHEN t.name='FAN PIT' THEN 499900 WHEN t.name='ON STAGE' THEN 699900 WHEN t.name='EM LOUNGE' THEN 999900 ELSE 3000000 END,t.capacity,t.admissions FROM events e CROSS JOIN (VALUES ('GENERAL ACCESS',200,1),('VIP',200,1),('FAN PIT',200,1),('ON STAGE',200,1),('EM LOUNGE',200,1),('TABLES STARTING',200,6)) AS t(name,capacity,admissions) ON CONFLICT(event_id,name) DO NOTHING;
